344	    /**
345	     * Reduces a telephone number to its canonical E.164 form so that differently formatted but
346	     * equivalent numbers compare equal. A value already stored that cannot form valid E.164
347	     * (e.g. unusual legacy data) falls back to its digits-only form rather than failing lookup.
348	     */
349	    private static String normalizeTelephone(String telephone) {
350	        if (telephone == null) {
351	            return null;
352	        }
353	        try {
354	            return TelephoneNormalizer.toE164(telephone);
355	        } catch (InvalidTelephoneException ex) {
356	            return telephone.replaceAll("\\D", "");
357	        }
358	    }
